/*
 PLAN
 1. Composition: backdrop gradient plane 7x6 at z=-2.5; hero rounded-rect CTA button (2.6x0.68, bevel 0.03) centered at y=0.15 as the monolith subject; MSDF label on face; caption 0.25 below; contact shadow plane 0.08 under.
 2. Light rig (rig-underglow-signal): key dir #f8f4ee 2.4 @ [1.4,3,2]; red practical point #ff2a38 int 14 @ [0,-0.65,0.6] d6; rim dir #fff 1.3 @ [-1.4,2,-2.4]; ambient floor 0.08.
 3. Materials: face MeshPhysicalNodeMaterial with TSL vertical engineered 3-stop red gradient + hard seam at 50%; roughness 0.5, metalness 0.35, clearcoat 0.22; perimeter emissive channel #ff2a38 int 1.6 via TSL edge mask.
 4. Motion: weighted-settle 1.04->1.0 0.9s power4.out on mount; hover z 0->0.06 + edge emissive 1.6->2.2 180ms; press scale 0.97 120ms with shadow tighten; idle breathing <=2%.
 5. Focal: the gradient CTA slab — brightest read via emissive edge + red underglow; everything else graded darker.
*/
import { MeshPhysicalNodeMaterial, MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, vec3, vec2, float, mix, smoothstep, step, min, max, abs, sub, uniform, positionLocal } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const {
    Group, Mesh, Shape, ExtrudeGeometry, PlaneGeometry, CircleGeometry,
    DirectionalLight, PointLight, AmbientLight, Color,
  } = THREE;

  const root = new Group();
  root.name = 'gradient-cta-node';

  const disposables = [];
  const timelines = [];
  const primitiveHandles = [];

  const colors = config.intent?.visualSpec?.colors ?? {};
  const C = {
    background: colors.background ?? '#0b0b10',
    surface: colors.surface ?? '#16161d',
    ink: colors.ink ?? '#16161d',
    paper: colors.paper ?? '#e8ecf2',
    accent: colors.accent ?? '#ff2a38',
  };
  const stops = colors.gradientStops ?? [
    { at: 0, hex: '#ff4450' },
    { at: 0.55, hex: '#ff2a38' },
    { at: 1, hex: '#c1121f' },
  ];

  // ---------- backdropStage: graded stage plane, never void (DL16) ----------
  function backdropStage() {
    const geo = new PlaneGeometry(7, 6);
    const mat = new MeshBasicNodeMaterial();
    const bg = new Color(C.background);
    const surf = new Color(C.surface);
    const acc = new Color(C.accent);
    const v = uv().y;
    // vertical grade: surface glow low (red practical spill), near-black top
    const base = mix(vec3(bg.r, bg.g, bg.b).mul(0.85), vec3(surf.r, surf.g, surf.b).mul(1.15), smoothstep(0.0, 0.75, v).oneMinus());
    const spill = vec3(acc.r, acc.g, acc.b).mul(smoothstep(0.55, 0.0, v).mul(0.14));
    // soft radial vignette lift behind subject
    const d = uv().sub(vec2(0.5, 0.42)).length();
    const halo = vec3(surf.r, surf.g, surf.b).mul(smoothstep(0.55, 0.0, d).mul(0.5));
    mat.colorNode = base.add(spill).add(halo);
    const mesh = new Mesh(geo, mat);
    mesh.position.set(0, 0, -2.5);
    disposables.push(geo, mat);
    return mesh;
  }
  root.add(backdropStage());

  // ---------- lightRig: rig-underglow-signal (node-local) ----------
  function lightRig() {
    const g = new Group();
    const amb = new AmbientLight(0xffffff, 0.08);
    const key = new DirectionalLight(0xf8f4ee, 1.2); // capped per doctrine (rim/accent <=1.5 node-local)
    key.position.set(1.4, 3, 2);
    key.target.position.set(0, 0.4, 0);
    const practical = new PointLight(new Color(C.accent), 14, 6, 2);
    practical.position.set(0, -0.65, 0.6);
    const rim = new DirectionalLight(0xffffff, 1.3);
    rim.position.set(-1.4, 2, -2.4);
    rim.target.position.set(0, 0.5, 0);
    g.add(amb, key, key.target, practical, rim, rim.target);
    return g;
  }
  root.add(lightRig());

  // ---------- button group ----------
  const buttonGroup = new Group();
  buttonGroup.position.set(0, 0.15, 0);
  root.add(buttonGroup);

  const W = 2.6, H = 0.68, R = 0.08, DEPTH = 0.03;

  // ctaButton: rounded-rect extruded slab with 45deg chamfer bevel
  function roundedRectShape(w, h, r) {
    const s = new Shape();
    const x = -w / 2, y = -h / 2;
    s.moveTo(x + r, y);
    s.lineTo(x + w - r, y);
    s.absarc(x + w - r, y + r, r, -Math.PI / 2, 0, false);
    s.lineTo(x + w, y + h - r);
    s.absarc(x + w - r, y + h - r, r, 0, Math.PI / 2, false);
    s.lineTo(x + r, y + h);
    s.absarc(x + r, y + h - r, r, Math.PI / 2, Math.PI, false);
    s.lineTo(x, y + r);
    s.absarc(x + r, y + r, r, Math.PI, Math.PI * 1.5, false);
    return s;
  }

  // gradientFace: engineered 3-stop gradient + hard seam + perimeter emissive channel (TSL)
  const emissiveIntensity = uniform(1.6);
  function ctaMaterial() {
    const mat = new MeshPhysicalNodeMaterial({
      roughness: 0.5,
      metalness: 0.35,
      clearcoat: 0.22,
      clearcoatRoughness: 0.4,
    });
    const c0 = new Color(stops[0].hex);
    const c1 = new Color(stops[1].hex);
    const c2 = new Color(stops[2].hex);
    const acc = new Color(C.accent);
    // vertical param across face height using local position (extrude UVs are unreliable)
    const t = positionLocal.y.add(float(H / 2)).div(float(H)).clamp(0, 1);
    const g01 = mix(vec3(c2.r, c2.g, c2.b), vec3(c1.r, c1.g, c1.b), smoothstep(0.0, float(stops[1].at), t));
    const grad = mix(g01, vec3(c0.r, c0.g, c0.b), smoothstep(float(stops[1].at), 1.0, t));
    // hard 0.01-unit seam line at 50% face height — zero soft blur
    const seamHalf = float(0.005 / H);
    const seam = step(abs(t.sub(0.5)), seamHalf);
    const face = mix(grad, grad.mul(1.35), seam);
    mat.colorNode = face;
    // perimeter emissive channel 0.015 wide in accent
    const px = positionLocal.x, py = positionLocal.y;
    const dx = float(W / 2).sub(abs(px));
    const dy = float(H / 2).sub(abs(py));
    const edgeDist = min(dx, dy);
    const channel = smoothstep(float(0.02), float(0.015), edgeDist).mul(step(float(0.0), edgeDist));
    mat.emissiveNode = vec3(acc.r, acc.g, acc.b).mul(channel).mul(emissiveIntensity);
    return mat;
  }

  const btnGeo = new ExtrudeGeometry(roundedRectShape(W, H, R), {
    depth: DEPTH,
    bevelEnabled: true,
    bevelThickness: DEPTH,
    bevelSize: DEPTH, // 45deg chamfer catches key light as machined edge
    bevelSegments: 1,
    curveSegments: 24,
  });
  const btnMat = ctaMaterial();
  const btn = new Mesh(btnGeo, btnMat);
  disposables.push(btnGeo, btnMat);
  buttonGroup.add(btn);

  // ---------- ctaLabel: MSDF label centered on face ----------
  function ctaLabel() {
    const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
    const labelItem = items.find((i) => i.role === 'cta-label') ?? { text: 'BEGIN COMMISSION' };
    const capItem = items.find((i) => i.role === 'caption') ?? { text: 'NO DEPOSIT REQUIRED' };

    const label = ctx.fontAtlas.createText(String(labelItem.text), {
      fontSize: labelItem.typography?.fontSize ?? 20,
      color: C.paper,
      align: 'center',
      letterSpacingPx: 1.6,
      maxWidthPx: 512,
    });
    label.position.set(0, 0, DEPTH * 2 + 0.011);
    buttonGroup.add(label);

    const caption = ctx.fontAtlas.createText(String(capItem.text), {
      fontSize: capItem.typography?.fontSize ?? 9,
      color: C.paper,
      align: 'center',
      letterSpacingPx: 1.1,
      maxWidthPx: 512,
    });
    caption.position.set(0, -(H / 2) - 0.25, 0.01);
    buttonGroup.add(caption);
  }
  ctaLabel();

  // ---------- contactShadow: radial plane 0.08 below ----------
  const shadowMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  {
    const ink = new Color(C.ink);
    const d = uv().sub(vec2(0.5, 0.5)).length().mul(2.0);
    shadowMat.colorNode = vec3(ink.r, ink.g, ink.b).mul(0.15);
    shadowMat.opacityNode = smoothstep(1.0, 0.15, d).mul(0.35);
  }
  const shadowGeo = new CircleGeometry(1.0, 48);
  const contactShadow = new Mesh(shadowGeo, shadowMat);
  contactShadow.rotation.x = -Math.PI / 2;
  contactShadow.scale.set(W * 0.65, H * 1.4, 1);
  contactShadow.position.set(0, 0.15 - H / 2 - 0.08, 0);
  disposables.push(shadowGeo, shadowMat);
  root.add(contactShadow);

  // ---------- motion ----------
  // mountSettle: weighted-settle 1.04 -> 1.0 over 900ms
  buttonGroup.scale.setScalar(1.04);
  const mountTl = gsap.timeline();
  mountTl.to(buttonGroup.scale, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' });
  timelines.push(mountTl);

  // idle: single slow breathing <=2%
  const idleTl = gsap.timeline({ repeat: -1, yoyo: true, delay: 1.0 });
  idleTl.to(buttonGroup.scale, { x: 1.015, y: 1.015, z: 1.015, duration: 3.2, ease: 'sine.inOut' });
  timelines.push(idleTl);

  // ---------- interaction handlers ----------
  let hoverTl = null, pressTl = null;
  root.userData.handlers = {
    pointerenter: () => {
      if (hoverTl) hoverTl.kill();
      hoverTl = gsap.timeline();
      hoverTl.to(buttonGroup.position, { z: 0.06, duration: 0.18, ease: 'power2.out' }, 0);
      hoverTl.to(emissiveIntensity, { value: 2.2, duration: 0.18, ease: 'power2.out' }, 0);
      timelines.push(hoverTl);
    },
    pointerleave: () => {
      if (hoverTl) hoverTl.kill();
      hoverTl = gsap.timeline();
      hoverTl.to(buttonGroup.position, { z: 0, duration: 0.18, ease: 'power2.out' }, 0);
      hoverTl.to(emissiveIntensity, { value: 1.6, duration: 0.18, ease: 'power2.out' }, 0);
      timelines.push(hoverTl);
    },
    pointerdown: () => {
      if (pressTl) pressTl.kill();
      idleTl.pause();
      pressTl = gsap.timeline();
      pressTl.to(buttonGroup.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out(1.7)' }, 0);
      // contact shadow tightens on press
      pressTl.to(contactShadow.scale, { x: W * 0.58, y: H * 1.2, duration: 0.12, ease: 'power2.out' }, 0);
      timelines.push(pressTl);
    },
    pointerup: () => {
      if (pressTl) pressTl.kill();
      pressTl = gsap.timeline({ onComplete: () => idleTl.resume() });
      pressTl.to(buttonGroup.scale, { x: 1, y: 1, z: 1, duration: 0.25, ease: 'power3.out' }, 0);
      pressTl.to(contactShadow.scale, { x: W * 0.65, y: H * 1.4, duration: 0.25, ease: 'power3.out' }, 0);
      timelines.push(pressTl);
    },
    click: () => {
      ctx.emit('cta:begin-commission', { nodeId: config.id ?? 'gradient-cta' });
    },
  };

  // ---------- primitives from config (none expected, applied if present) ----------
  for (const p of config.cinematicPrimitives ?? []) {
    const fn = ctx.primitives?.[p.name];
    if (fn) primitiveHandles.push(fn(buttonGroup, p.params ?? {}));
  }

  // ---------- cleanup ----------
  root.userData.cleanup = () => {
    for (const tl of timelines) tl.kill();
    if (hoverTl) hoverTl.kill();
    if (pressTl) pressTl.kill();
    for (const h of primitiveHandles) h?.cleanup?.();
    for (const d of disposables) d?.dispose?.();
    root.traverse((obj) => {
      if (obj.geometry?.dispose && !disposables.includes(obj.geometry)) obj.geometry.dispose();
      if (obj.material?.dispose && !disposables.includes(obj.material)) obj.material.dispose();
    });
  };

  return root;
}

/* @spec-manifest
{"elements":[
{"id":"text.cta-label.0","where":"ctaLabel","how":"MSDF label centered on button face"},
{"id":"text.caption.1","where":"ctaLabel","how":"MSDF caption 0.25 below button"},
{"id":"color.background","where":"backdropStage","how":"stage gradient base color"},
{"id":"color.surface","where":"backdropStage","how":"stage grade upper tone and halo"},
{"id":"color.ink","where":"contactShadow","how":"contact shadow tint"},
{"id":"color.paper","where":"ctaLabel","how":"label and caption text color"},
{"id":"color.accent","where":"ctaMaterial","how":"perimeter emissive channel and practical light"},
{"id":"color.gradient","where":"ctaMaterial","how":"3-stop vertical TSL gradient on face"},
{"id":"effects.spec","where":"ctaButton","how":"rounded-rect extrude, chamfer, seam, emissive, motion"}
]}
*/
